+// API keys and roles. A key is { key, name, role } in `apiKeys`. Roles grant
+// actions: `viewer` may read; `cook` may also cook, record waste, log
+// temperatures and enter stock-take counts; `manager` may do everything.
+import { createHash, timingSafeEqual } from "node:crypto";
+import { AppError } from "../errors.js";
+
+/** What each role may do. */
+export const ROLES = Object.freeze({
+  viewer: Object.freeze(["read"]),
+  cook: Object.freeze(["read", "cook"]),
+  manager: Object.freeze(["read", "cook", "manage"]),
+});
+
+const digest = (s) => createHash("sha256").update(String(s)).digest();
+
+/** The API key record for a bearer token; throws `unauthorized` when missing or unknown. */
+export function authenticate(store, token) {
+  if (typeof token !== "string" || token === "") throw new AppError("unauthorized");
+  const wanted = digest(token);
+  const found = (store.data.apiKeys ?? []).find((k) => typeof k.key === "string" && timingSafeEqual(digest(k.key), wanted));
+  if (!found || !(found.role in ROLES)) throw new AppError("unauthorized");
+  return found;
+}
+
+/** Throws `forbidden` unless the key's role may do `action` ("read", "cook" or "manage"). */
+export function authorize(apiKey, action) {
+  if (!ROLES[apiKey.role]?.includes(action)) throw new AppError("forbidden", { role: apiKey.role });
+}
