+import test from "node:test";
+import assert from "node:assert/strict";
+import { app, as } from "./helpers.js";
+
+test("no key or an unknown key is 401 in the error shape", async () => {
+  const { handle } = app();
+  for (const headers of [{}, { authorization: "Bearer nope" }, { authorization: "Basic viewer-dev-key" }]) {
+    const res = await handle({ path: "/items", headers });
+    assert.equal(res.status, 401);
+    assert.equal(res.body.error.code, "unauthorized");
+    assert.ok(res.body.error.message);
+  }
+});
+
+test("viewers may read but not change anything", async () => {
+  const { handle, store } = app();
+  assert.equal((await handle({ path: "/items", headers: as("viewer") })).status, 200);
+  const before = JSON.stringify(store.data.batches);
+  const res = await handle({ method: "POST", path: "/recipes/1/cook", headers: as("viewer"), body: { portions: 1 } });
+  assert.equal(res.status, 403);
+  assert.equal(res.body.error.code, "forbidden");
+  assert.equal(JSON.stringify(store.data.batches), before);
+});
+
+test("cooks may cook, waste, log temperatures and count, but nothing else", async () => {
+  const { handle } = app();
+  const cook = as("cook");
+  assert.equal((await handle({ method: "POST", path: "/recipes/1/cook", headers: cook, body: { portions: 1 } })).status, 200);
+  assert.equal((await handle({ method: "POST", path: "/batches/1/waste", headers: cook, body: { qty: 0.5 } })).status, 201);
+  assert.equal((await handle({ method: "POST", path: "/temperatures", headers: cook, body: { location: "fridge", celsius: 3 } })).status, 201);
+  assert.equal((await handle({ method: "POST", path: "/stocktakes", headers: cook, body: { location: "dry" } })).status, 403);
+  const take = (await handle({ method: "POST", path: "/stocktakes", headers: as("manager"), body: { location: "dry" } })).body;
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, headers: cook, body: { batchId: 6, counted: 12 } })).status, 200);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/finish`, headers: cook })).status, 403);
+  assert.equal((await handle({ method: "POST", path: "/jobs/nightly", headers: cook })).status, 403);
+  assert.equal((await handle({ path: "/audit", headers: cook })).status, 403);
+});
+
+test("changes are audited, newest first, for managers only", async () => {
+  const { handle } = app();
+  await handle({ method: "POST", path: "/recipes/1/cook", headers: as("cook"), body: { portions: 1 } });
+  await handle({ method: "POST", path: "/jobs/nightly", headers: as("cook") });
+  await handle({ path: "/items", headers: as("cook") });
+  assert.equal((await handle({ path: "/audit", headers: as("viewer") })).status, 403);
